{'code': "from qgis.PyQt.QtWidgets import QMenu, QToolBar, QAction
mw = iface.mainWindow()
out = []
for a in mw.findChildren(QAction):
    if (a.text() or '') == 'ツールボックスにスクリプトを追加...':
        conts = []
        for w in a.associatedObjects():
            if isinstance(w, QMenu):
                conts.append('QMenu:%s [%s]' % (w.title(), w.objectName()))
            elif isinstance(w, QToolBar):
                conts.append('QToolBar:%s' % w.windowTitle())
            else:
                conts.append(w.metaObject().className())
        out.append({'text': a.text(), 'objectName': a.objectName(), 'enabled': a.isEnabled(), 'visible': a.isVisible(), 'toolTip': a.toolTip(), 'statusTip': a.statusTip(), 'shortcut': a.shortcut().toString(), 'containers': conts})
result = out"}
